static bool skip_section(const InSection&s){auto n=lower(s.name);if(s.chars&0x00000800u)return true;if(n==".drectve"||n==".llvm_addrsig"||n.rfind(".debug",0)==0||n==".comment")return true;return false;}
struct OutSection { std::string name;std::vector<uint8_t> data;uint32_t virtual_size=0,rva=0,raw=0,raw_size=0,chars=0; };
static int group_for(const InSection&s){if(s.chars&0x00000020u)return 0;if(s.chars&0x80000000u)return 2;return 1;}
static size_t group_align(int g){return g==0?16u:8u;}

struct ImportDesc {std::string exact,canonical,dll;bool indirect=false;};
static std::string undecorate(std::string n){if(n.rfind("__imp_",0)==0)n=n.substr(6);else if(n.rfind("_imp__",0)==0)n=n.substr(6);if(!n.empty()&&n[0]=='_')n.erase(n.begin());auto at=n.find('@');if(at!=std::string::npos){bool digits=at+1<n.size();for(size_t i=at+1;i<n.size();++i)digits=digits&&std::isdigit((unsigned char)n[i]);if(digits)n=n.substr(0,at);}return n;}
static bool is_indirect_import(const std::string&n){return n.rfind("__imp_",0)==0||n.rfind("_imp__",0)==0;}
static std::string import_dll(const std::string&canon){
    static const std::unordered_set<std::string> crt={"printf","puts","putchar","sprintf","snprintf","malloc","calloc","realloc","free","memcpy","memmove","memset","strlen","strcmp","strncmp","atoi","strtol","exit","abort"};
    static const std::unordered_set<std::string> k32={"ExitProcess","GetStdHandle","WriteFile","ReadFile","Sleep","GetLastError","SetLastError"};
    if(crt.count(canon))return "msvcrt.dll";if(k32.count(canon))return "kernel32.dll";return "";
}

struct DefRef {size_t obj=0;uint32_t sym=0;};
struct LinkState {bool x64=false;uint16_t machine=0;uint64_t image_base=0;std::vector<Object> objs;std::unordered_map<std::string,DefRef> globals;std::vector<OutSection> outs;std::vector<ImportDesc> imports;std::unordered_map<std::string,size_t> import_by_canon;std::unordered_map<std::string,uint32_t> import_target;std::unordered_map<std::string,uint32_t> iat_target;};
