struct IdataBuild{std::vector<uint8_t> bytes;};
static IdataBuild build_idata(const std::vector<ImportDesc>& imports,bool x64){IdataBuild z;std::map<std::string,std::vector<size_t>> groups;for(size_t i=0;i<imports.size();++i)groups[imports[i].dll].push_back(i);size_t desc_count=groups.size()+1;z.bytes.resize(desc_count*20u,0);size_t ptr=x64?8:4;for(auto&kv:groups){z.bytes.resize(alignsz(z.bytes.size(),ptr),0);z.bytes.resize(z.bytes.size()+(kv.second.size()+1)*ptr,0);z.bytes.resize(z.bytes.size()+(kv.second.size()+1)*ptr,0);}for(auto&i:imports){z.bytes.resize(alignsz(z.bytes.size(),2),0);w16(z.bytes,0);z.bytes.insert(z.bytes.end(),i.canonical.begin(),i.canonical.end());z.bytes.push_back(0);}for(auto&kv:groups){z.bytes.insert(z.bytes.end(),kv.first.begin(),kv.first.end());z.bytes.push_back(0);}return z;}
