static void usage(){std::cout<<"jauld 0.1\nusage: jauld <input.obj> [more.obj ...] -o <program.exe> --target <windows-x86_64|windows-x86>\n";}
int main(int argc,char**argv){try{if(argc<2){usage();return 0;}std::vector<std::string>in;std::string out="a.exe",target;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="-o"&&i+1<argc)out=argv[++i];else if(a=="--target"&&i+1<argc)target=argv[++i];else if(a=="--help"||a=="-h"){usage();return 0;}else in.push_back(a);}if(target.empty()){auto o=read_coff(in.at(0));target=o.machine==0x8664?"windows-x86_64":"windows-x86";}return link_pe(in,out,target);}catch(const std::exception&e){std::cerr<<"jauld: "<<e.what()<<"\n";return 1;}}
